import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import ReminderIcon from '@mui/icons-material/NotificationsActive';
import {
  Button,
  Card,
  CardActions,
  CardContent,
  Grid,
  IconButton,
  Tooltip,
  Typography,
  Box,
  Chip,
  Divider,
  Link,
} from '@mui/material';
import React, { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import DeletePopup from '../../components/ModelPopup/DeletePopup';
import ReminderPopup from '../../components/ModelPopup/ReminderPopup';
import {
  ICompanyDetails,
  ICompanyDetailsData,
  IPrivilege,
} from '../../core/Interface/company.interface';
import { useNotifier } from '../../core/Notifier';
import useUser from '../../core/hooks/useUser';
import { Privileges } from '../../core/types/commonType';
import { appColors } from '../../theme/appColors';
import TopInfoSkeleton from '../Dashboard/TopInfoSkeleton';
import { useDeleteCompanyMutation, useGetAllCompanyQuery, useSendPaymentReminderMutation } from '../posApi';
import NewCompany from './components/NewCompany';
import AnimatedPage from '../../layouts/AnimatedPage';
import FormatListBulletedIcon from '@mui/icons-material/FormatListBulleted';
import CompanyDetails from './components/CompanyDetails';
import KeyIcon from '@mui/icons-material/Key';
import PrivilegesDialog from './components/Privileges';
import dayjs from 'dayjs';
import { formatDate } from '../../core/utils';
import WhatsAppIcon from '@mui/icons-material/WhatsApp';
import { alpha } from '@mui/material/styles';

// Converts a local Sri Lankan number (07XXXXXXXX / 7XXXXXXXX) to a wa.me link
const getWhatsAppLink = (contactNo: string) => {
  const digits = contactNo.replace(/\D/g, '');
  const international = digits.startsWith('94')
    ? digits
    : `94${digits.replace(/^0/, '')}`;
  return `https://wa.me/${international}`;
};

const Company = () => {
  const { t } = useTranslation(['common', 'usermanage', 'category', 'company']);
  const [companyData, setCompanyData] = React.useState<
    ICompanyDetailsData | undefined
  >();
  const { userHasRight } = useUser();
  const { showErrorMessage, showMessage } = useNotifier();
  const [openAddCompany, setOpenAddCompany] = useState(false);
  const [openDeleteCompany, setOpenDeleteCompany] = useState(false);
  const [companyNameToDelete, setCompanyNameToDelete] = useState('');
  const [openReminderPopup, setOpenReminderPopup] = useState(false);
  const [companyNameForReminder, setCompanyNameForReminder] = useState('');
  const [openCompanyDetails, setOpenCompanyDetails] = useState(false);
  const [openPrivilege, setOpenPrivilege] = useState(false);
  const [userPrivilegeData, setUserPrivilegeData] =
    React.useState<IPrivilege[]>();


  const { data, isLoading } = useGetAllCompanyQuery({
    pageIndex: 0,
    pageSize: 50,
    searchText: '',
  });

  const companyList = useMemo(() => {
    return data?.data as ICompanyDetails;
  }, [data?.data]);

  const [deleteCompany] = useDeleteCompanyMutation();
  const [sendPaymentReminder] = useSendPaymentReminderMutation();

  const handleDelete = async (id: string) => {
    try {
      const response = await deleteCompany(id).unwrap();
      if (response.status) {
        showMessage(response.message);
        setOpenDeleteCompany(false);
      } else {
        showErrorMessage(response.message);
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const handleSendReminder = async (id: string) => {
    try {
      const response = await sendPaymentReminder(id).unwrap();
      if (response.status) {
        showMessage(response.message);
        setOpenReminderPopup(false);
      } else {
        showErrorMessage(response.message);
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  return (
    <AnimatedPage>
      <Box data-testid="company">
        <Box sx={{ py: { xs: 1, sm: 2 } }}>
          <Grid
            container
            display="flex"
            flexDirection="row"
            item
            justifyContent="flex-end"
            key={3}
          >
            {userHasRight(Privileges.CompanyManageAdd) && (
              <Button
                onClick={() => {
                  setCompanyData(undefined);
                  setOpenAddCompany(true);
                }}
                startIcon={<AddIcon />}
                sx={{
                  mr: { xs: 0, sm: 2 },
                  mb: 0,
                  width: { xs: '100%', sm: 200 },
                  border: 'none',
                  backgroundColor: appColors.darkGreen[20],
                  marginTop: { xs: '8px', sm: '20px' },
                  borderRadius: '8px',
                  cursor: 'pointer',
                  height: '42px',
                  fontWeight: 'bold',
                  '&:hover': {
                    backgroundColor: appColors.greyishBlue[20],
                  },
                }}
                variant="outlined"
              >
                {' '}
                {t('category:addCompany')}
              </Button>
            )}
          </Grid>
        </Box>
        {openAddCompany && (
          <NewCompany
            data={companyData}
            handleCloseDialog={() => setOpenAddCompany(false)}
            openModel={openAddCompany}
            title={`${companyData
              ? t('usermanage:editCompany')
              : t('usermanage:addNewCompany')
              } `}
          />
        )}

        {openDeleteCompany && (
          <DeletePopup
            content={`${t(
              'company:deleteConfirmMessage'
            )} "${companyNameToDelete}"?`}
            handleCloseDelete={() => setOpenDeleteCompany(false)}
            onConfirm={async () => {
              await handleDelete(companyData?.id.toString() || '');
            }}
            open={openDeleteCompany}
            title={t('company:deleteCompany')}
          />
        )}

        {openReminderPopup && (
          <ReminderPopup
            content={`${t(
              'company:confirmMessage'
            )} "${companyNameForReminder}"?`}
            handleCloseReminder={() => setOpenReminderPopup(false)}
            onConfirm={async () => {
              await handleSendReminder(companyData?.id.toString() || '');
            }}
            open={openReminderPopup}
            title={t('company:reminderTitle')}
          />
        )}

        <Grid
          container
          spacing={{ xs: 2, md: 4 }}
        >
          {!isLoading &&
            companyList &&
            companyList.records.map((value, index) => (
              <Grid
                item
                key={index}
                md={4}
                sm={6}
                xs={12}
              >
                <Card
                  sx={{
                    p: 0,
                    m: 0,
                    width: '100%',
                    maxWidth: '100%',
                    height: '100%',
                    display: 'flex',
                    flexDirection: 'column',
                    justifyContent: 'space-between',
                  }}
                >
                  <CardContent
                    sx={{
                      backgroundColor: value.isEnabled ? '' : '#F4EBEC',
                      wordBreak: 'break-word',
                      flexGrow: 1,
                    }}
                  >
                    <Box
                      sx={{
                        display: 'flex',
                        alignItems: 'flex-start',
                        justifyContent: 'space-between',
                        gap: 1,
                        mb: 1.5,
                      }}
                    >
                      <Box sx={{ minWidth: 0 }}>
                        <Typography
                          sx={{ fontWeight: 700, lineHeight: 1.3 }}
                          variant="subtitle1"
                        >
                          {value.name}
                        </Typography>
                        <Typography
                          color="text.secondary"
                          variant="caption"
                        >
                          {t('category:title.code')}: {value.code}
                        </Typography>
                      </Box>
                      <Chip
                        color={value.isEnabled ? 'success' : 'error'}
                        label={value.isEnabled ? 'Active' : 'Disabled'}
                        size="small"
                        sx={{ fontWeight: 600, flexShrink: 0 }}
                        variant="outlined"
                      />
                    </Box>
                    <Divider sx={{ mb: 1 }} />
                    <InfoRow
                      label={t('company:title.contactPerson')}
                      value={value.contactPerson || '-'}
                    />
                    <InfoRow
                      label={t('company:title.contactNo')}
                      value={
                        value.contactNo ? (
                          <Link
                            href={getWhatsAppLink(value.contactNo)}
                            rel="noopener noreferrer"
                            sx={{
                              display: 'inline-flex',
                              alignItems: 'center',
                              gap: 0.5,
                              color: '#25D366',
                            }}
                            target="_blank"
                            underline="hover"
                          >
                            <WhatsAppIcon sx={{ fontSize: 18 }} />
                            {value.contactNo}
                          </Link>
                        ) : (
                          '-'
                        )
                      }
                    />
                    <InfoRow
                      label={t('company:title.rootUsername')}
                      value={value.rootUser?.username || '-'}
                    />
                    <InfoRow
                      label={t('company:title.usersCount')}
                      value={value.usersCount ?? '-'}
                    />
                    <InfoRow
                      label={t('company:title.branchesCount')}
                      value={value.branchesCount ?? '-'}
                    />
                    <InfoRow
                      label={t('company:title.isImageEnabled')}
                      value={value.isImageEnabled ? 'Yes' : 'No'}
                    />
                    <InfoRow
                      highlight={
                        !value.maintenanceFeePaidUntil ||
                        dayjs(value.maintenanceFeePaidUntil).diff(
                          dayjs(),
                          'day'
                        ) <= 14
                      }
                      label={t('company:title.maintenanceFeePaidUntil')}
                      value={
                        value.maintenanceFeePaidUntil
                          ? formatDate(new Date(value.maintenanceFeePaidUntil))
                          : 'Not Available'
                      }
                    />
                  </CardContent>
                  <Divider />
                  <CardActions
                    sx={{
                      justifyContent: 'flex-end',
                      flexWrap: 'wrap',
                      gap: 1,
                      px: 2,
                      py: 1.25,
                      '& > :not(:first-of-type)': { ml: 0 },
                    }}
                  >
                    {userHasRight(Privileges.CompanyManageView) &&
                      value.maintenanceFeePaidUntil &&
                      dayjs(value.maintenanceFeePaidUntil).diff(
                        dayjs(),
                        'day'
                      ) <= 14 && (
                        <ActionButton
                          color={appColors.violetGrey[80]}
                          icon={<ReminderIcon fontSize="small" />}
                          label={t('company:reminderTitle')}
                          onClick={() => {
                            setCompanyData(value);
                            setCompanyNameForReminder(value.name);
                            setOpenReminderPopup(true);
                          }}
                        />
                      )}
                    {userHasRight(Privileges.CompanyManageView) && (
                      <ActionButton
                        color={appColors.reflexBlue[80]}
                        icon={<KeyIcon fontSize="small" />}
                        label={t('company:actions.viewPrivileges')}
                        onClick={() => {
                          setUserPrivilegeData(value.companyPrivileges);
                          setOpenPrivilege(true);
                        }}
                      />
                    )}
                    {userHasRight(Privileges.CompanyManageEdit) && (
                      <ActionButton
                        color={appColors.forestGreen[80]}
                        icon={<FormatListBulletedIcon fontSize="small" />}
                        label={t('company:actions.viewDetails')}
                        onClick={() => {
                          setCompanyData(value);
                          setOpenCompanyDetails(true);
                        }}
                      />
                    )}
                    {userHasRight(Privileges.CompanyManageEdit) && (
                      <ActionButton
                        color={appColors.amberYellow[80]}
                        icon={<EditIcon fontSize="small" />}
                        label={t('company:actions.editCompany')}
                        onClick={() => {
                          setCompanyData(value);
                          setOpenAddCompany(true);
                        }}
                      />
                    )}
                    {userHasRight(Privileges.CompanyManageDelete) && (
                      <ActionButton
                        color={appColors.carmineRed[80]}
                        icon={<DeleteIcon fontSize="small" />}
                        label={t('company:deleteCompany')}
                        onClick={() => {
                          setCompanyData(value);
                          setCompanyNameToDelete(value.name);
                          setOpenDeleteCompany(true);
                        }}
                      />
                    )}
                  </CardActions>
                </Card>
              </Grid>
            ))}
          {isLoading &&
            [1, 2, 3, 4].map((i) => (
              <Grid
                item
                key={i}
                md={4}
                sm={6}
                xs={12}
              >
                <TopInfoSkeleton data-testid="top--skeleton" />
              </Grid>
            ))}
          {!isLoading && companyList && companyList.records.length === 0 && (
            <Typography
              align="center"
              data-testid="top-nodata"
              width="100%"
            >
              {t('common:noData')}
            </Typography>
          )}
        </Grid>

        {companyData && openCompanyDetails && (
          <CompanyDetails
            data={companyData}
            open={openCompanyDetails}
            setOpen={setOpenCompanyDetails}
          />
        )}

        {userPrivilegeData && (
          <PrivilegesDialog
            data={userPrivilegeData}
            open={openPrivilege}
            setOpen={setOpenPrivilege}
          />
        )}
      </Box>
    </AnimatedPage>
  );
};

export default Company;

interface IInfoRow {
  label: string;
  value: React.ReactNode;
  highlight?: boolean;
}

// eslint-disable-next-line react/no-multi-comp
const InfoRow = ({ label, value, highlight = false }: IInfoRow) => (
  <Box
    sx={{
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'baseline',
      gap: 2,
      py: 0.5,
    }}
  >
    <Typography
      color="text.secondary"
      variant="body2"
    >
      {label}
    </Typography>
    <Typography
      color={highlight ? 'error.main' : 'text.primary'}
      sx={{ fontWeight: 600, textAlign: 'right' }}
      variant="body2"
    >
      {value}
    </Typography>
  </Box>
);

interface IActionButton {
  label: string;
  icon: React.ReactNode;
  color: string;
  onClick: () => void;
}

// eslint-disable-next-line react/no-multi-comp
const ActionButton = ({ label, icon, color, onClick }: IActionButton) => (
  <Tooltip
    arrow
    title={label}
  >
    <IconButton
      aria-label={label}
      onClick={onClick}
      sx={{
        width: 38,
        height: 38,
        borderRadius: 2,
        color,
        backgroundColor: alpha(color, 0.1),
        border: `1px solid ${alpha(color, 0.2)}`,
        transition: 'all 0.2s ease',
        '&:hover': {
          backgroundColor: color,
          color: '#fff',
        },
      }}
    >
      {icon}
    </IconButton>
  </Tooltip>
);
